import { App, Modal, Notice } from 'obsidian';
import type RadiProtocolPlugin from '../main';
import type { Snippet } from '../snippets/snippet-model';
import { SnippetFillInModal } from './snippet-fill-in-modal';
import { SnippetTreePicker } from './snippet-tree-picker';

export class InsertSnippetModal extends Modal {
  readonly result: Promise<string | null>;
  private resolve!: (value: string | null) => void;
  private resolved = false;
  private picker: SnippetTreePicker | null = null;

  constructor(app: App, private readonly plugin: RadiProtocolPlugin) {
    super(app);
    this.result = new Promise<string | null>((res) => {
      this.resolve = res;
    });
  }

  onOpen(): void {
    const { contentEl, titleEl } = this;
    contentEl.empty();
    titleEl.setText(this.plugin.i18n.t('insertSnippet.title'));

    const rootPath = this.plugin.settings.snippetFolderPath.trim();
    if (rootPath === '') {
      contentEl.createEl('p', { text: this.plugin.i18n.t('insertSnippet.setSnippetFolderFirst') });
      return;
    }

    const pickerHost = contentEl.createDiv({ cls: 'rp-insert-snippet-picker-host' });
    this.picker = new SnippetTreePicker({
      app: this.app,
      snippetService: this.plugin.snippetService,
      container: pickerHost,
      mode: 'file-only',
      rootPath,
      t: this.plugin.i18n.t.bind(this.plugin.i18n),
      onSelect: (result) => {
        void this.handleSelect(rootPath, result.relativePath);
      },
    });
    void this.picker.mount();
  }

  onClose(): void {
    this.picker?.unmount();
    this.picker = null;
    this.safeResolve(null);
    this.contentEl.empty();
  }

  private async handleSelect(rootPath: string, relativePath: string): Promise<void> {
    const path = relativePath === '' ? rootPath : `${rootPath}/${relativePath}`;
    const snippet = await this.plugin.snippetService.load(path);
    if (snippet === null) {
      new Notice(this.plugin.i18n.t('insertSnippet.notFound', { path }));
      return;
    }
    if (snippet.kind === 'json' && snippet.validationError !== null) {
      new Notice(this.plugin.i18n.t('insertSnippet.cannotBeUsed', { path, error: snippet.validationError }));
      return;
    }

    const rendered = await this.renderSnippetForInsert(snippet);
    if (rendered === null) return;
    this.safeResolve(rendered);
    super.close();
  }

  private async renderSnippetForInsert(snippet: Snippet): Promise<string | null> {
    if (snippet.kind === 'md') return snippet.content;
    if (snippet.placeholders.length === 0) return snippet.template;

    const fillModal = new SnippetFillInModal(this.app, snippet, this.plugin.i18n.t.bind(this.plugin.i18n));
    fillModal.open();
    return fillModal.result;
  }

  private safeResolve(value: string | null): void {
    if (this.resolved) return;
    this.resolved = true;
    this.resolve(value);
  }
}

// src/__tests__/views/snippet-tree-picker.test.ts
// Phase 51 PICKER-02 (Plan 02) — SnippetTreePicker unit tests.
//
// Covers:
//   D-08  three-mode surface (folder-only | file-only | both) + onSelect dispatch
//   D-09  mode-filtered search
//   D-10  case-insensitive substring matcher
//   D-11  two-line result rows (primary basename + secondary full-relative-path)
//   D-12  search-row click semantics + clearing-search-restores-drillPath
//   Phase 35 MD-01 preservation: extension-based file-glyph dispatch (📄 / 📝)
//
// Strategy: we install a local `vi.mock('obsidian', ...)` stub with a hand-rolled
// MockEl compatible with the SnippetTreePicker's DOM API (createEl / createDiv /
// empty / addEventListener). SnippetService is a plain vi.fn mock. No happy-dom.

import { describe, it, expect, beforeEach, vi } from 'vitest';

// ---------------------------------------------------------------------------
// Minimal DOM-ish mock element (mirrors src/__tests__/snippet-tree-view.test.ts)
// ---------------------------------------------------------------------------

interface MockClassList {
  add: (cls: string) => void;
  remove: (cls: string) => void;
  contains: (cls: string) => boolean;
  has: (cls: string) => boolean;
}

interface MockEl {
  tagName: string;
  children: MockEl[];
  parent: MockEl | null;
  _text: string;
  textContent: string;
  classList: MockClassList;
  _attrs: Record<string, string>;
  _style: Record<string, string>;
  _listeners: Map<string, Array<(ev: unknown) => void>>;
  dataset: Record<string, string>;
  value: string;
  placeholder: string;
  style: Record<string, string>;
  type: string;
  createEl: (tag: string, opts?: { text?: string; cls?: string; type?: string; attr?: Record<string, string> }) => MockEl;
  createDiv: (opts?: { cls?: string; text?: string }) => MockEl;
  createSpan: (opts?: { cls?: string; text?: string }) => MockEl;
  empty: () => void;
  setText: (text: string) => void;
  appendChild: (child: MockEl) => MockEl;
  addClass: (cls: string) => void;
  removeClass: (cls: string) => void;
  setAttribute: (k: string, v: string) => void;
  getAttribute: (k: string) => string | null;
  addEventListener: (type: string, handler: (ev: unknown) => void) => void;
  removeEventListener: (type: string, handler: (ev: unknown) => void) => void;
  dispatchEvent: (event: { type: string; target?: unknown }) => void;
  remove: () => void;
  focus: () => void;
}

function makeEl(tag = 'div'): MockEl {
  const listeners = new Map<string, Array<(ev: unknown) => void>>();
  const style: Record<string, string> = {};
  const attrs: Record<string, string> = {};
  const dataset: Record<string, string> = {};
  const classSet = new Set<string>();
  const classList: MockClassList = {
    add: (c: string) => { classSet.add(c); },
    remove: (c: string) => { classSet.delete(c); },
    contains: (c: string) => classSet.has(c),
    has: (c: string) => classSet.has(c),
  };
  const children: MockEl[] = [];
  const el: MockEl = {
    tagName: tag.toUpperCase(),
    children,
    parent: null,
    _text: '',
    textContent: '',
    classList,
    _attrs: attrs,
    _style: style,
    _listeners: listeners,
    dataset,
    value: '',
    placeholder: '',
    style,
    type: '',
    createEl(t: string, opts?: { text?: string; cls?: string; type?: string; attr?: Record<string, string> }): MockEl {
      const child = makeEl(t);
      child.parent = el;
      if (opts?.text !== undefined) { child._text = opts.text; child.textContent = opts.text; }
      if (opts?.cls) {
        for (const c of opts.cls.split(/\s+/)) child.classList.add(c);
      }
      if (opts?.type !== undefined) { child.type = opts.type; }
      if (opts?.attr) {
        for (const [k, v] of Object.entries(opts.attr)) child._attrs[k] = v;
      }
      children.push(child);
      return child;
    },
    createDiv(opts?: { cls?: string; text?: string }): MockEl {
      return el.createEl('div', opts);
    },
    createSpan(opts?: { cls?: string; text?: string }): MockEl {
      return el.createEl('span', opts);
    },
    empty(): void {
      children.length = 0;
    },
    setText(text: string): void {
      el._text = text;
      el.textContent = text;
    },
    appendChild(child: MockEl): MockEl {
      child.parent = el;
      children.push(child);
      return child;
    },
    addClass(cls: string): void { classSet.add(cls); },
    removeClass(cls: string): void { classSet.delete(cls); },
    setAttribute(k: string, v: string): void { attrs[k] = v; },
    getAttribute(k: string): string | null { return attrs[k] ?? null; },
    addEventListener(type: string, handler: (ev: unknown) => void): void {
      const arr = listeners.get(type) ?? [];
      arr.push(handler);
      listeners.set(type, arr);
    },
    removeEventListener(type: string, handler: (ev: unknown) => void): void {
      const arr = listeners.get(type);
      if (!arr) return;
      const idx = arr.indexOf(handler);
      if (idx >= 0) arr.splice(idx, 1);
    },
    dispatchEvent(event: { type: string; target?: unknown }): void {
      const arr = listeners.get(event.type) ?? [];
      for (const h of arr) h(event);
    },
    remove(): void {
      const p = el.parent;
      if (!p) return;
      const idx = p.children.indexOf(el);
      if (idx >= 0) p.children.splice(idx, 1);
      el.parent = null;
    },
    focus(): void {},
  };
  return el;
}

